'use client';

import { useEffect, useRef } from 'react';
import { useMenuCategoryNav } from '../context/MenuCategoryNavContext';

export type MenuCategoryNavPlacement = 'inline' | 'header';

interface MenuCategoryNavProps {
  placement: MenuCategoryNavPlacement;
}

export function MenuCategoryNav({ placement }: MenuCategoryNavProps) {
  const { categories, activeId, scrollToCategory } = useMenuCategoryNav();
  const navRef = useRef<HTMLElement>(null);

  useEffect(() => {
    if (placement !== 'inline' || !navRef.current || !activeId) {
      return;
    }

    const activeButton = navRef.current.querySelector(`[data-category-id="${activeId}"]`);
    if (activeButton instanceof HTMLElement) {
      activeButton.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
    }
  }, [activeId, placement]);

  if (categories.length <= 1) {
    return null;
  }

  return (
    <nav
      ref={navRef}
      className={`restaurant-menu__category-nav restaurant-menu__category-nav--${placement}`}
      aria-label="Навигация по категориям меню"
    >
      <div className="restaurant-menu__category-nav-inner">
        {categories.map((category) => (
          <button
            key={category.id}
            type="button"
            data-category-id={category.id}
            className={`restaurant-menu__category-nav-btn${
              activeId === category.id ? ' restaurant-menu__category-nav-btn--active' : ''
            }`}
            onClick={() => scrollToCategory(category.id)}
          >
            {category.name}
          </button>
        ))}
      </div>
    </nav>
  );
}
